import React, { useEffect } from 'react'
import { ToastContainer } from 'react-toastify'
import RetailPrescriptionsTable from './RetailPrescriptionsTable'
import useApi from '../../../hooks/useApi'
import retailersApi from '../../../api/retailers/retailersApi'
import { useNavigate } from 'react-router-dom'

const columns = [
    { name: "Patient", uid: "patient_title" },
    { name: "Gender", uid: "patient_gender" },
    { name: "Date of Birth", uid: "patient_date_of_birth" },
    { name: "Age (Yrs)", uid: "patient_age" },
    { name: "Comment", uid: "comment" },
    { name: "Items", uid: "items_count" },
    { name: "Date Added", uid: "created" },
    { name: "Actions", uid: "actions" },
];

export default function RetailPrescriptions() {
    const [data, setData] = React.useState([])

    const [errors, setErrors] = React.useState([])
   const navigate = useNavigate()

    const handleEditAction = (item) => {
                navigate(`/retailers/orders/prescriptions/cost/${item.id}`,{
            state: {
                'prescription': item
            }
        });
    }

    const handleAddAction = (e) => {
       
        console.log("Add action triggered",e);
        // Implement your add action logic here     
    }
    const handleDetailsAction = (item) => {
                navigate(`/retailers/orders/prescriptions/details/${item.id}`,{
            state: {
                'prescription': item
            }
        });
        console.log("Edit action for item:", item);
        // Implement your edit action logic here    
    }
    const handleDeleteAction = (item) => {
        console.log("Delete action for item:", item);
        // Implement your delete action logic here  
    }

    const handleFilter = (filter) => {
        console.log("Filter action with filter:", filter);
        // Implement your filter action logic here
    }

    const getEntityRetailPrescriptionsApi = useApi(retailersApi.retailPrescriptionsAction);

    const getEntityRetailPrescriptions = async () => {

        await getEntityRetailPrescriptionsApi.request({
            action: "RetrieveEntityRetailPrescriptions",
        });
    }
    useEffect(() => {
        if (getEntityRetailPrescriptionsApi.data) {
            if (getEntityRetailPrescriptionsApi.data.length) {
                setData(getEntityRetailPrescriptionsApi.data);
            }
        }
    }, [getEntityRetailPrescriptionsApi.data]);

    useEffect(() => {
        getEntityRetailPrescriptions();
    }, []);


    return (
        <div className="mt-16 md:mt-2">
            <ToastContainer theme="colored" position="bottom-center" />
            <RetailPrescriptionsTable
                title={"Retail Prescriptions"}
                data={data}
                columns={columns}
                editAction={handleEditAction}
                detailsAction={handleDetailsAction}
                deleteAction={handleDeleteAction}
                addAction={handleAddAction}
                handleFilter={handleFilter}
            />
        </div>
    )
}
